INSERT IGNORE INTO books (id, title, author, description, price, category, image_url, rating, stock) VALUES
(1, 'The Midnight Library', 'Matt Haig', 'Between life and death there is a library, and within that library, the shelves go on forever. Every book provides a chance to try another life you could have lived.', 14.99, 'Fiction', 'https://picsum.photos/seed/midnightlibrary/400/600', 4.6, 32),
(2, 'The Silent Patient', 'Alex Michaelides', 'Alicia Berenson writes a single word after shooting her husband five times: silence. A psychotherapist becomes obsessed with treating her and uncovering the truth.', 12.49, 'Mystery', 'https://picsum.photos/seed/silentpatient/400/600', 4.5, 21),
(3, 'Dune', 'Frank Herbert', 'Set on the desert planet Arrakis, Dune is the story of Paul Atreides, heir to a noble family tasked with ruling an inhospitable world where the only thing of value is the "spice".', 16.99, 'Sci-Fi', 'https://picsum.photos/seed/dunebook/400/600', 4.8, 40),
(4, 'Project Hail Mary', 'Andy Weir', 'Ryland Grace wakes up on a spaceship with no memory of how he got there, tasked with saving humanity from extinction, in this gripping tale of survival and discovery.', 15.49, 'Sci-Fi', 'https://picsum.photos/seed/hailmary/400/600', 4.9, 18),
(5, 'It Ends with Us', 'Colleen Hoover', 'A powerful and emotional story about love, resilience, and the courage to break a cycle, following Lily Bloom as she navigates a complicated romance.', 11.99, 'Romance', 'https://picsum.photos/seed/itendswithus/400/600', 4.4, 27),
(6, 'The Seven Husbands of Evelyn Hugo', 'Taylor Jenkins Reid', 'Reclusive Hollywood icon Evelyn Hugo finally decides to give her life story to an unknown magazine reporter, revealing sacrifices made to become a legend.', 13.99, 'Romance', 'https://picsum.photos/seed/evelynhugo/400/600', 4.7, 24),
(7, 'Atomic Habits', 'James Clear', 'An easy and proven way to build good habits and break bad ones, offering a practical framework for improving every day through tiny, incremental changes.', 17.99, 'Self-Help', 'https://picsum.photos/seed/atomichabits/400/600', 4.8, 50),
(8, 'The Subtle Art of Not Giving a F*ck', 'Mark Manson', 'A counterintuitive approach to living a good life, challenging conventional self-help wisdom by teaching readers to focus only on what truly matters.', 13.49, 'Self-Help', 'https://picsum.photos/seed/subtleart/400/600', 4.3, 35),
(9, 'Clean Code', 'Robert C. Martin', 'A handbook of agile software craftsmanship that teaches the principles, patterns, and practices of writing genuinely clean, maintainable code.', 34.99, 'Technology', 'https://picsum.photos/seed/cleancode/400/600', 4.7, 15),
(10, 'Designing Data-Intensive Applications', 'Martin Kleppmann', 'A deep dive into the ideas behind reliable, scalable, and maintainable systems, exploring databases, distributed systems, and data engineering.', 39.99, 'Technology', 'https://picsum.photos/seed/ddia/400/600', 4.9, 12),
(11, 'And Then There Were None', 'Agatha Christie', 'Ten strangers are lured to an isolated island, each with a dark secret, and one by one they are killed off in this classic murder mystery.', 10.99, 'Mystery', 'https://picsum.photos/seed/thenwerenone/400/600', 4.7, 29),
(12, 'Gone Girl', 'Gillian Flynn', 'On the morning of his fifth wedding anniversary, Nick Dunne''s wife disappears, and his portrait of a blissful marriage begins to crumble in this dark thriller.', 12.99, 'Mystery', 'https://picsum.photos/seed/gonegirl/400/600', 4.4, 22),
(13, 'The Hobbit', 'J.R.R. Tolkien', 'Bilbo Baggins, a hobbit who enjoys a comfortable life, is swept into an epic quest to reclaim the Lonely Mountain from the fearsome dragon Smaug.', 11.49, 'Fiction', 'https://picsum.photos/seed/thehobbit/400/600', 4.8, 38),
(14, 'Normal People', 'Sally Rooney', 'A story that follows the complex relationship between Connell and Marianne, from their school days in a small town to university life in Dublin.', 12.29, 'Romance', 'https://picsum.photos/seed/normalpeople/400/600', 4.2, 19),
(15, 'The Martian', 'Andy Weir', 'Stranded alone on Mars after his crew presumes him dead, astronaut Mark Watney must use his ingenuity and wit to survive against overwhelming odds.', 14.29, 'Sci-Fi', 'https://picsum.photos/seed/themartian/400/600', 4.7, 26),
(16, 'Deep Work', 'Cal Newport', 'A guide to cultivating focus in a distracted world, arguing that the ability to concentrate without distraction is becoming increasingly valuable and rare.', 16.49, 'Self-Help', 'https://picsum.photos/seed/deepwork/400/600', 4.6, 33),
